\mathsf{Init}_{GQ}
=
\{(M,g):M=(D,I_{\mathcal F},I_{\mathcal R},I_{\mathcal Q})\in
\mathsf{Struct}_{GQ}^{\Sigma,\mathcal Q}
\land g:\mathsf{Var}\to D\},

\Delta_{GQ}
\Longleftrightarrow
\mathsf{Feature}_{GQ}
=(\mathcal Q,\operatorname{type}_{\mathcal Q},\operatorname{InterpQ},\operatorname{gq})
\land
\forall Q\in\mathcal Q\,
\operatorname{type}_{\mathcal Q}(Q)\in\mathbb N^{<\omega}
\land
\forall M,g,Q,(\vec x_j,A_j)_{j<r}\,
\bigl((M,g,\operatorname{gq}(Q,(\vec x_j,A_j)_{j<r}))\in\mathsf{Sat}_{GQ}
\Longleftrightarrow
(\mathsf{GQArg}_{GQ}(M,g,Q,(\vec x_j,A_j)_{j<r},j))_{j<r}
\in\mathsf{QInterp}_{GQ}(M,Q)\bigr).
